const l=s=>s.split('|');
const choice=(title,next)=>({title:l(title),next});
export function completeMaintenanceRoutes(nodes,sources){
 sources.chamberFanReplacement='https://help.prusa3d.com/guide/how-to-replace-the-chamber-fan-core-one_944814';
 nodes['chamber-fan-check'].choices.unshift(choice('交換が必要と確認できた|Replacement is confirmed necessary|Výměna je potvrzena jako nutná|Austausch ist als notwendig bestätigt','chamber-fan-replace'));
 nodes['chamber-fan-replace']={title:l('チャンバーファンの交換へ進む|Open chamber fan replacement|Přejít k výměně komorového ventilátoru|Zum Austausch des Kammerlüfters'),body:l('清掃・接続の確認と実機のファンテストを行い、背面のチャンバーファンの交換が必要と確認できた場合に進みます。対応する交換品を用意し、下の交換手順を最初から開いてください。冷却と電源の切断から順に進めます。判断できない場合はサポートへ相談してください。|Continue after inspection, connection checks and the printer fan test have confirmed that a rear chamber fan needs replacement. Prepare the correct replacement and open the procedure below from the beginning. Follow cooling and power disconnection in order. Contact support if you are unsure.|Pokračujte až po kontrole, ověření konektorů a testu na tiskárně, pokud je potvrzena nutnost výměny zadního komorového ventilátoru. Připravte správný náhradní díl a níže otevřete postup od začátku. Dodržte pořadí vychladnutí a odpojení napájení. Při nejistotě kontaktujte podporu.|Fahren Sie erst fort, wenn Prüfung, Anschlusskontrolle und Lüftertest am Drucker bestätigen, dass ein hinterer Kammerlüfter ersetzt werden muss. Legen Sie das passende Ersatzteil bereit und öffnen Sie die Anleitung unten von Anfang an. Halten Sie Abkühlen und Netztrennung in der angegebenen Reihenfolge ein. Wenden Sie sich bei Unsicherheit an den Support.'),sources:['chamberFanReplacement'],tasks:['chamber-fan'],taskSteps:{'chamber-fan':0},choices:[choice('対処後の確認へ進む|Check after the repair|Kontrola po opravě|Nach der Reparatur prüfen','resolved'),choice('判断できないので相談する|Unsure: contact support|Nejistota: kontaktovat podporu|Unsicher: Support kontaktieren','support')]};
 sources.clogNeedle='https://help.prusa3d.com/article/clogged-nozzle-core-one-core-one-l-xl-mk4-s-mk3-9-s_411823#procedures-that-require-nozzle-heating';
 sources.motorCheck='https://help.prusa3d.com/article/clogged-nozzle-core-one-core-one-l-xl-mk4-s-mk3-9-s_411823#how-to-fix-the-clogged-printer';
 sources.manualColdPull='https://help.prusa3d.com/article/cold-pull-31702-core-one-35702-core-one-l_930551#manual-cold-pull';
 nodes['nonhf-needle']={title:l('非HF限定の清掃針手順|Non-HF-only cleaning-needle method|Postup s jehlou pouze bez HF|Reinigungsnadel nur für Nicht-HF'),body:l('装着品が非HFと確認できた場合だけ選びます。HFや種類不明なら針を入れません。下の作業を開き、加熱から吐出確認まで順に進めます。|Choose only after confirming the installed nozzle is non-HF. Do not insert a needle into HF or unidentified nozzles. Open the procedure below and follow heating through the extrusion check in order.|Zvolte pouze po ověření trysky bez HF. Do HF trysky ani neznámého typu jehlu nezavádějte. Níže otevřete postup a pokračujte od ohřevu ke kontrole extruze.|Nur bei bestätigter Nicht-HF-Düse wählen. Keine Nadel in HF-Düsen oder unbekannte Typen einführen. Verfahren unten öffnen und vom Heizen bis zur Extrusionsprüfung der Reihe nach vorgehen.'),sources:['clogNeedle','nozzleTypes'],tasks:['needle-clear'],taskSteps:{'needle-clear':0},inspection:{task:'needle-clear',step:0},choices:[choice('HF・不明なので別の方法へ|HF or unknown: another method|HF nebo neznámá: jiný postup|HF oder unbekannt: anderes Verfahren','hotend-path')]};
 for(const id of ['partial','blocked-remedy'])nodes[id].choices.push(choice('非HFと確認済み：清掃針の手順|Confirmed non-HF: needle procedure|Ověřená tryska bez HF: postup s jehlou|Nicht-HF bestätigt: Nadelverfahren','nonhf-needle'));
 nodes['motor-check-ready']={title:l('Nextruderモーター軸の点検|Nextruder motor-shaft check|Kontrola hřídele motoru Nextruderu|Nextruder-Motorwelle prüfen'),body:l('簡易清掃後も送り不良が残る場合の別作業です。PGアダプターを先に用意し、冷却・抜栓から進みます。固着した部品をこじる手順ではありません。|A separate procedure for feeding trouble remaining after simple cleaning. Prepare the PG adapter first and begin with cooling and unplugging. This does not instruct prying stuck parts free.|Samostatný postup pro potíže po jednoduchém čištění. Nejprve připravte PG adaptér a začněte vychladnutím a odpojením. Nejde o páčení zaseklých dílů.|Eigenes Verfahren bei Förderproblemen nach einfacher Reinigung. PG-Adapter zuerst bereitlegen und mit Abkühlen und Netztrennung beginnen. Festsitzende Teile werden nicht herausgehebelt.'),sources:['motorCheck'],tasks:['motor-check'],taskSteps:{'motor-check':0},choices:[choice('部品が固着して外せない|Parts are stuck|Díly jsou zaseklé|Teile sitzen fest','gear-stuck')]};
 nodes.gear.choices.push(choice('簡易清掃でも改善しない：モーター軸を点検|Still unresolved after simple cleaning: inspect motor shaft|Čištění nepomohlo: kontrola hřídele motoru|Nach Reinigung ungelöst: Motorwelle prüfen','motor-check-ready'));
 const compatible=nodes['coldpull-compatibility'].choices.find(c=>c.next==='coldpull-ready');if(!compatible)throw Error('Missing original cold-pull compatibility route');compatible.next='coldpull-method';
 nodes['coldpull-method']={title:l('自動か手動を選ぶ|Choose automatic or manual|Zvolit automatický nebo ruční postup|Automatisch oder manuell wählen'),body:l('一部でも吐出し、対応ノズルと確認できた場合です。自動は実機のCold Pull案内に従います。手動はPLAを270°Cで充填し、冷却後100°Cで引きます。2つの温度やタイミングを混ぜません。|For some remaining flow and a confirmed compatible nozzle. Automatic follows the printer Cold Pull prompts. Manual fills with PLA at 270 °C and pulls at 100 °C after cooling. Do not mix their temperatures or timing.|Pro částečný tok a ověřenou vhodnou trysku. Automatický postup sleduje pokyny Cold Pull tiskárny. Ruční naplní PLA při 270 °C a po ochlazení táhne při 100 °C. Teploty a načasování nemíchejte.|Bei Teilfluss und bestätigter geeigneter Düse. Automatisch folgt den Cold-Pull-Anzeigen des Druckers. Manuell wird bei 270 °C mit PLA gefüllt und nach Abkühlen bei 100 °C gezogen. Temperaturen und Zeitpunkte nicht vermischen.'),sources:['cold','manualColdPull'],choices:[choice('実機の自動Cold Pull|Automatic Cold Pull on the printer|Automatický Cold Pull na tiskárně|Automatischer Cold Pull am Drucker','coldpull-ready'),choice('手動コールドプル|Manual cold pull|Ruční cold pull|Manueller Cold Pull','manual-coldpull-ready')]};
 nodes['manual-coldpull-ready']={title:l('手動コールドプルの手順|Manual cold-pull procedure|Postup ručního cold pullu|Manueller Cold-Pull-Ablauf'),body:l('PLAを用意し、上部継手の取外しから設定の復旧まで順に進めます。完全詰まりやNozzle Xには使いません。|Prepare PLA and follow the procedure from inlet access to restored settings. Do not use on a complete blockage or Nozzle X.|Připravte PLA a pokračujte od přístupu shora po obnovení nastavení. Nepoužívejte při úplném ucpání ani s Nozzle X.|PLA bereitlegen und vom Zugang oben bis zum Wiederherstellen der Einstellungen vorgehen. Nicht bei vollständiger Verstopfung oder Nozzle X verwenden.'),sources:['manualColdPull'],tasks:['coldpull-manual'],taskSteps:{'coldpull-manual':0},choices:[choice('完全に出ないので詰まりの確認へ|No flow: check blockage|Bez toku: kontrola ucpání|Kein Fluss: Verstopfung prüfen','blocked')]};
}
